set -u
cd /root/mojolearn
O=$LEG_OUT/exp1; mkdir -p $O
echo '' | base64 -d > /root/extract_amdgpu.py
echo '' | base64 -d > /root/base_hw_eval.mojo
cp holtwinters/impl/internal/hw_eval.mojo /root/patched_hw_eval.mojo
cmp -s /root/base_hw_eval.mojo /root/patched_hw_eval.mojo && echo "PATCH NOT PRESENT" >> $O/notes.txt
ENVP=$(pixi run printenv CONDA_PREFIX); echo "CONDA_PREFIX=$ENVP" >> $O/notes.txt
pixi run printenv | grep -i modular >> $O/notes.txt
pixi run mojo --version >> $O/notes.txt 2>&1
pixi run mojo build --help > $O/mojo_build_help.txt 2>&1
pixi run mojo build --help-hidden > $O/mojo_build_help_hidden.txt 2>&1
nproc >> $O/notes.txt
FLAGS="--target-cpu x86-64-v3 --target-accelerator gfx942 -D MOJOLEARN_NUMERIC_IDENTICAL=1 -I . -I bindings"
# one build per isolated MODULAR_HOME copy (no shared cache); args: variant idx jobs
onebuild() {
  v=$1; i=$2; j=$3
  H=/root/mh/$v-$i; rm -rf $H; mkdir -p /root/mh; cp -r $ENVP/share/max $H; rm -rf $H/cache $H/.mojo_cache
  W=/root/w/$v-$i; mkdir -p $W
  t=$(date +%s)
  pixi run env MODULAR_HOME=$H mojo build -j $j --emit shared-lib $FLAGS bindings/_mojolearn_tsa.mojo -o $W/_mojolearn_tsa.so > $W/build.log 2>&1
  rc=$?
  sha=$(sha256sum $W/_mojolearn_tsa.so 2>/dev/null | cut -c1-16)
  cos=$(python3 -c "
import sys; sys.path.insert(0,'/root'); import extract_amdgpu as e
print(','.join(x[2][:8] for x in e.extract(sys.argv[1])))" $W/_mojolearn_tsa.so 2>/dev/null)
  printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' $v $i $j $rc $(( $(date +%s)-t )) $sha "$cos" >> $O/builds.tsv
  find $H -maxdepth 3 -name "*cache*" 2>/dev/null | head -3 > $W/cache_ls.txt
}
# first: confirm isolation (one build, then check the shared env cache did not grow)
du -s $ENVP/share/max/cache 2>/dev/null > $O/shared_cache_before.txt
cp /root/base_hw_eval.mojo holtwinters/impl/internal/hw_eval.mojo
for i in 1 2 3 4; do onebuild base $i 1 & done; wait
for i in 5 6 7 8; do onebuild base $i 1 & done; wait
for i in 9 10 11 12; do onebuild base $i 1 & done; wait
cp /root/patched_hw_eval.mojo holtwinters/impl/internal/hw_eval.mojo
for i in 1 2 3 4; do onebuild patched $i 1 & done; wait
for i in 5 6 7 8; do onebuild patched $i 1 & done; wait
for i in 9 10 11 12; do onebuild patched $i 1 & done; wait
du -s $ENVP/share/max/cache 2>/dev/null > $O/shared_cache_after.txt
# keep one binary per distinct sha per variant
for v in base patched; do for f in /root/w/$v-*/_mojolearn_tsa.so; do s=$(sha256sum $f | cut -c1-16); mkdir -p $O/so/$v; [ -f $O/so/$v/$s.so ] || cp $f $O/so/$v/$s.so; done; done
tail -5 /root/w/base-1/build.log > $O/sample_build.log
